using System;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace Dafeiyu {
internal sealed class LocalCompanionImportWindow:Window {
readonly CancellationTokenSource cancellation=new CancellationTokenSource();bool finished;
private LocalCompanionImportWindow(){Width=440;Height=210;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=ThemeManager.Surface;LocalizedUi.Set(this,"Title",()=>TextResources.Get("companionImport.title"));var panel=new StackPanel{Margin=new Thickness(22)};panel.Children.Add(LocalizedUi.Text(()=>TextResources.Get("companionImport.progress"),14));var bar=new ProgressBar{IsIndeterminate=true,Height=5,Margin=new Thickness(0,20,0,18)};panel.Children.Add(bar);var cancel=LocalizedUi.Button(()=>TextResources.Get("dialog.cancelImport"));cancel.Name="CancelCompanionImport";cancel.IsCancel=true;cancel.Click+=delegate{cancellation.Cancel();cancel.IsEnabled=false;LocalizedUi.Set(cancel,"Content",()=>TextResources.Get("dialog.cancelling"));};panel.Children.Add(cancel);panel.Margin=new Thickness(0);Height=260;DialogUi.ApplyTitled(this,Ui.Scroll(panel));Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs args){if(!finished){cancellation.Cancel();cancel.IsEnabled=false;LocalizedUi.Set(cancel,"Content",()=>TextResources.Get("dialog.cancelling"));args.Cancel=true;}};}
internal static async Task<T> RunAsync<T>(Window owner,Func<CancellationToken,T> import){var dialog=new LocalCompanionImportWindow{Owner=owner};Task<T> task=null;dialog.Loaded+=async delegate{task=Task.Run(()=>import(dialog.cancellation.Token));try{await task;}catch(Exception){/* The caller observes the original task below. */}finally{dialog.finished=true;dialog.Close();}};try{dialog.ShowDialog();T result=await task;PetWindow.PlayApplicationCue(NotificationCue.Complete,"import:"+Guid.NewGuid().ToString("N"));return result;}catch(OperationCanceledException){throw;}catch(Exception){PetWindow.PlayApplicationCue(NotificationCue.Failure,"import:"+Guid.NewGuid().ToString("N"));throw;}finally{dialog.cancellation.Dispose();}}
}}
